#!/system/bin/sh
# Phone-side lifecycle manager for the loopback-only Qwen llama.cpp server.
# It signals only the PID it recorded and only after /proc matches the exact
# server, model, and port.

umask 077
SCRIPT_DIR=${0%/*}
if [ "$SCRIPT_DIR" = "$0" ]; then
  SCRIPT_DIR=.
fi
SCRIPT_DIR=$(CDPATH='' cd -- "$SCRIPT_DIR" 2>/dev/null && pwd)
TEXT_COMPANION_ROOT=${TEXT_COMPANION_ROOT:-$SCRIPT_DIR}
if [ -f "$TEXT_COMPANION_ROOT/env.sh" ]; then
  # env.sh is generated by deploy.sh from validated, fixed phone paths.
  # shellcheck disable=SC1091
  . "$TEXT_COMPANION_ROOT/env.sh"
fi

TEXT_SERVER=${TEXT_SERVER:-}
TEXT_NATIVE_LIB_DIR=${TEXT_NATIVE_LIB_DIR:-}
TEXT_MODEL=${TEXT_MODEL:-$TEXT_COMPANION_ROOT/models/Qwen3-1.7B-Q4_0.gguf}
TEXT_MODEL_BYTES=${TEXT_MODEL_BYTES:-1056782912}
TEXT_MODEL_SHA256=${TEXT_MODEL_SHA256:-c876f159707a4e4f70e045106c69db15bfc935a4981706fd4f65c6e7ea1e81c5}
TEXT_PORT=${TEXT_PORT:-6020}
TEXT_CTX_SIZE=${TEXT_CTX_SIZE:-2048}
TEXT_THREADS=${TEXT_THREADS:-4}
TEXT_BATCH_THREADS=${TEXT_BATCH_THREADS:-4}
TEXT_BATCH_SIZE=${TEXT_BATCH_SIZE:-128}
TEXT_UBATCH_SIZE=${TEXT_UBATCH_SIZE:-64}
PID_FILE=${TEXT_PID_FILE:-$TEXT_COMPANION_ROOT/text-companion.pid}
LOG_FILE=${TEXT_LOG_FILE:-$TEXT_COMPANION_ROOT/text-companion.log}

case "$TEXT_PORT" in 6020) ;; *) echo "TEXT_PORT must remain 6020" >&2; exit 2 ;; esac
case "$TEXT_CTX_SIZE" in 256|384|512|768|1024|1536|2048) ;;
  *) echo "TEXT_CTX_SIZE must be a bounded value from 256 through 2048" >&2; exit 2 ;;
esac
case "$TEXT_THREADS" in 1|2|3|4) ;;
  *) echo "TEXT_THREADS must be between 1 and 4" >&2; exit 2 ;;
esac
case "$TEXT_BATCH_THREADS" in 1|2|3|4) ;;
  *) echo "TEXT_BATCH_THREADS must be between 1 and 4" >&2; exit 2 ;;
esac
case "$TEXT_BATCH_SIZE:$TEXT_UBATCH_SIZE" in
  64:32|128:32|128:64|256:64) ;;
  *) echo "Unsupported bounded batch/microbatch pair" >&2; exit 2 ;;
esac

is_expected_pid() {
  pid=$1
  case "$pid" in ''|*[!0-9]*) return 1 ;; esac
  [ -r "/proc/$pid/cmdline" ] || return 1
  command_line=$(toybox tr '\000' ' ' < "/proc/$pid/cmdline" 2>/dev/null)
  case "$command_line" in *"$TEXT_SERVER"*) ;; *) return 1 ;; esac
  case "$command_line" in *"--model $TEXT_MODEL"*) ;; *) return 1 ;; esac
  case "$command_line" in *"--port 6020"*) ;; *) return 1 ;; esac
  return 0
}

read_pid() {
  [ -f "$PID_FILE" ] || return 1
  pid=$(toybox head -n 1 "$PID_FILE" | toybox tr -d ' \t\r\n')
  is_expected_pid "$pid"
}

verify_model() {
  [ -f "$TEXT_MODEL" ] || { echo "Missing model: $TEXT_MODEL" >&2; return 2; }
  actual_bytes=$(toybox wc -c < "$TEXT_MODEL" | toybox tr -d ' \t\r\n')
  [ "$actual_bytes" = "$TEXT_MODEL_BYTES" ] || {
    echo "Model size mismatch: $actual_bytes != $TEXT_MODEL_BYTES" >&2
    return 3
  }
  hash_line=$(toybox sha256sum "$TEXT_MODEL" 2>/dev/null) || return 3
  set -- $hash_line
  actual_hash=${1:-}
  [ "$actual_hash" = "$TEXT_MODEL_SHA256" ] || {
    echo "Model SHA-256 mismatch: $actual_hash" >&2
    return 3
  }
}

verify_runtime() {
  [ -n "$TEXT_SERVER" ] && [ -x "$TEXT_SERVER" ] || {
    echo "Missing executable packaged server: $TEXT_SERVER" >&2
    return 2
  }
  [ -n "$TEXT_NATIVE_LIB_DIR" ] && [ -d "$TEXT_NATIVE_LIB_DIR" ] || {
    echo "Missing packaged native library directory: $TEXT_NATIVE_LIB_DIR" >&2
    return 2
  }
  for filename in \
    libllama-server-impl.so libllama-common.so libmtmd.so libllama.so \
    libggml.so libggml-base.so \
    libggml-cpu-android_armv8.0_1.so libggml-cpu-android_armv8.2_1.so \
    libggml-cpu-android_armv8.2_2.so libggml-cpu-android_armv8.6_1.so \
    libggml-cpu-android_armv9.0_1.so libggml-cpu-android_armv9.2_1.so \
    libggml-cpu-android_armv9.2_2.so LICENSE; do
    [ -f "$TEXT_NATIVE_LIB_DIR/$filename" ] || {
      echo "Missing packaged runtime file: $TEXT_NATIVE_LIB_DIR/$filename" >&2
      return 2
    }
  done
}

health() {
  response="$TEXT_COMPANION_ROOT/health.$$.tmp"
  models_response="$TEXT_COMPANION_ROOT/models.$$.tmp"
  toybox rm -f "$response"
  toybox rm -f "$models_response"
  printf 'GET /health HTTP/1.1\r\nHost: 127.0.0.1:6020\r\nConnection: close\r\n\r\n' | \
    toybox nc -w 5 127.0.0.1 6020 > "$response" 2>/dev/null
  result=$?
  if [ "$result" -eq 0 ] && \
     toybox grep -q '^HTTP/1\.[01] 200 ' "$response" && \
     toybox grep -q '"status"[[:space:]]*:[[:space:]]*"ok"' "$response"; then
    printf 'GET /v1/models HTTP/1.1\r\nHost: 127.0.0.1:6020\r\nConnection: close\r\n\r\n' | \
      toybox nc -w 5 127.0.0.1 6020 > "$models_response" 2>/dev/null
    models_result=$?
    if [ "$models_result" -eq 0 ] && \
       toybox grep -q '^HTTP/1\.[01] 200 ' "$models_response" && \
       toybox grep -q '"id"[[:space:]]*:[[:space:]]*"Qwen3-1.7B-Q4_0"' "$models_response"; then
      toybox cat "$response"
      toybox cat "$models_response"
      toybox rm -f "$response" "$models_response"
      return 0
    fi
  fi
  toybox cat "$response" 2>/dev/null
  toybox cat "$models_response" 2>/dev/null
  toybox rm -f "$response" "$models_response"
  return 1
}

port_responds() {
  printf 'GET /health HTTP/1.1\r\nHost: 127.0.0.1:6020\r\nConnection: close\r\n\r\n' | \
    toybox nc -w 1 127.0.0.1 6020 >/dev/null 2>&1
}

start_service() {
  if read_pid; then
    echo "Text companion already running as PID $pid"
    health
    return $?
  fi
  if [ -f "$PID_FILE" ]; then
    echo "Removing stale text companion PID file; no process was signalled" >&2
    toybox rm -f "$PID_FILE"
  fi
  if port_responds; then
    echo "Port 6020 has an unmanaged listener; refusing to start" >&2
    return 5
  fi
  verify_runtime || return $?
  verify_model || return $?
  toybox mkdir -p "$TEXT_COMPANION_ROOT/tmp" "$TEXT_COMPANION_ROOT/home"
  (
    cd "$TEXT_COMPANION_ROOT" || exit 2
    export LD_LIBRARY_PATH="$TEXT_NATIVE_LIB_DIR"
    export TMPDIR="$TEXT_COMPANION_ROOT/tmp"
    export HOME="$TEXT_COMPANION_ROOT/home"
    exec nohup "$TEXT_SERVER" \
      --model "$TEXT_MODEL" \
      --alias Qwen3-1.7B-Q4_0 \
      --ctx-size "$TEXT_CTX_SIZE" \
      --threads "$TEXT_THREADS" \
      --threads-batch "$TEXT_BATCH_THREADS" \
      --threads-http 1 \
      --batch-size "$TEXT_BATCH_SIZE" \
      --ubatch-size "$TEXT_UBATCH_SIZE" \
      --parallel 1 \
      --n-gpu-layers 0 \
      --jinja \
      --reasoning off \
      --reasoning-budget 0 \
      --reasoning-format deepseek \
      --host 127.0.0.1 \
      --port 6020 \
      --no-webui \
      --metrics \
      --log-colors off
  ) >> "$LOG_FILE" 2>&1 </dev/null &
  launched_pid=$!
  printf '%s\n' "$launched_pid" > "$PID_FILE"

  tries=0
  while [ "$tries" -lt 120 ]; do
    if ! is_expected_pid "$launched_pid"; then
      echo "Text companion exited during startup; inspect $LOG_FILE" >&2
      toybox rm -f "$PID_FILE"
      return 3
    fi
    if health >/dev/null; then
      echo "Text companion ready on 127.0.0.1:6020 (PID $launched_pid)"
      return 0
    fi
    sleep 1
    tries=$((tries + 1))
  done
  echo "Text companion did not become healthy; inspect $LOG_FILE" >&2
  stop_service
  return 4
}

stop_service() {
  if ! read_pid; then
    echo "Text companion is not running; no process was signalled"
    toybox rm -f "$PID_FILE"
    return 0
  fi
  target_pid=$pid
  kill "$target_pid" 2>/dev/null || true
  tries=0
  while [ "$tries" -lt 20 ]; do
    if ! is_expected_pid "$target_pid"; then
      toybox rm -f "$PID_FILE"
      echo "Text companion stopped"
      return 0
    fi
    sleep 1
    tries=$((tries + 1))
  done
  echo "Text companion PID $target_pid did not stop; refusing to escalate" >&2
  return 5
}

case "${1:-status}" in
  start) start_service ;;
  stop) stop_service ;;
  restart) stop_service && start_service ;;
  status)
    if read_pid; then
      echo "Text companion running as PID $pid"
      health
    else
      echo "Text companion is not running"
      exit 1
    fi
    ;;
  health) health ;;
  verify) verify_runtime && verify_model ;;
  log) toybox tail -n "${2:-100}" "$LOG_FILE" ;;
  *)
    echo "Usage: $0 {start|stop|restart|status|health|verify|log [lines]}" >&2
    exit 2
    ;;
esac
